# R62 S7 (B19/B20/B21) blind predictions generator. Authored per-case; writes one JSON per case.
import json, pathlib
OUT = pathlib.Path('/home/hatch/workspace/divination/benchmark/phase3/runs/round62/predictions')
OUT.mkdir(parents=True, exist_ok=True)

F = {'changed_main': False, 'reserve_used': False, 'disputed': False, 'reason': ''}
def trig(cm=False, ru=False, di=False, reason=''):
    return {'changed_main': cm, 'reserve_used': ru, 'disputed': di, 'reason': reason}

CASES = []
def add(cid, pred, basis, conf, trigger=None):
    CASES.append({'case_id': cid, 'prediction_text': pred, 'basis': basis, 'confidence': conf,
                  'trigger': trigger if trigger is not None else dict(F)})

LY_HDR = "tradition=liuyao（输入卡 tradition 字段明载）"
def ly(cid, pred, chain, conf, trigger):
    basis = LY_HDR + "\nsystems_used=六爻纳甲（用神旺衰＋动化定性裁决＋应期三步双层表达）\n" + chain
    add(cid, pred, basis, conf, trigger)

